(* Hysteresis control — prevents chatter near setpoint *)
IF Process_Value > High_Setpoint THEN
    Control_Output := TRUE;
END_IF;
IF Process_Value < Low_Setpoint THEN
    Control_Output := FALSE;
END_IF;

(* Alarm detection outside safe band *)
High_Alarm    := Process_Value > High_High_Setpoint;
Low_Alarm     := Process_Value < Low_Low_Setpoint;
Process_Fault := High_Alarm OR Low_Alarm;
